const IMG={};
function preload(list){
  return Promise.all(list.map(src=>new Promise(res=>{
    const im=new Image();
    im.onload=im.onerror=()=>res();
    const _u = _EMBUTIDO[src];
    if(!_u){ res(); return; }                 // asset não embutido: ignora
    im.src=_u; IMG[src]=im;
  })));
}
