// ============================================================
//  IK de 2 ossos
// ============================================================
function ik2(sh,target,l1,l2,bend){
  let dx=target.x-sh.x, dy=target.y-sh.y;
  let d=Math.hypot(dx,dy);
  d=Math.max(Math.abs(l1-l2)+0.5, Math.min(l1+l2-0.5, d));
  const base=Math.atan2(dy,dx);
  const cosA=(l1*l1+d*d-l2*l2)/(2*l1*d);
  const ang=Math.acos(Math.max(-1,Math.min(1,cosA)));
  const a=base+bend*ang;
  const el={x:sh.x+l1*Math.cos(a), y:sh.y+l1*Math.sin(a)};
  // punho exatamente no alvo (igual ao rig_engine.py)
  const wr={x:sh.x+dx, y:sh.y+dy};
  return {el,wr,a};
}

// ============================================================
//  desenho de camada rotacionada
// ============================================================
// sprite inteiro com pivo local (maos do kit)
function blit(ctx, img, pivX, pivY, tgtX, tgtY, rotDeg, scale=1){
  if(!ok(img)) return;
  ctx.save();
  ctx.translate(tgtX,tgtY);
  ctx.rotate(rotDeg*Math.PI/180);
  ctx.scale(scale,scale);
  ctx.drawImage(img, -pivX, -pivY);
  ctx.restore();
}
// colagem em DOIS pontos: gira em torno de (ax0,ay0) e desloca para que o
// segundo ponto do sprite caia exatamente em (ax1,ay1) — deslocamento aplicado
// DEPOIS da rotação, no espaço da tela.
function blit2(ctx, img, ax0, ay0, bx0, by0, ax1, ay1, bx1, by1, rotDeg){
  if(!ok(img)) return;
  const C=Math.cos(rotDeg*D2R), S=Math.sin(rotDeg*D2R);
  const rx = (bx0-ax0)*C - (by0-ay0)*S;
  const ry = (bx0-ax0)*S + (by0-ay0)*C;
  const ox = (ax1 + rx), oy = (ay1 + ry);
  ctx.save();
  ctx.translate(ox, oy);
  ctx.rotate(rotDeg*D2R);
  ctx.drawImage(img, -ax0, -ay0);
  ctx.restore();
}

// camada ancorada em DOIS pontos (cotovelo e punho):
// gira em torno do cotovelo e escolhe o deslocamento que faz a outra
// extremidade cair exatamente no punho.
function blitAncora(ctx, img, pivX, pivY, elx, ely, wrx, wry, rotDeg){
  if(!ok(img)) return;
  const dx = wrx - elx, dy = wry - ely;
  const d  = Math.hypot(dx,dy) || 1;
  const ux = dx/d, uy = dy/d;
  // ponto do sprite que deve cair no punho (na arte, é o punho desenhado)
  const fx = pivX, fy = pivY;                   // referência: pivô
  // deslocamento necessário
  const ox = (fx-pivX), oy = (fy-pivY);
  ctx.save();
  ctx.translate(elx, ely);
  ctx.rotate(rotDeg*D2R);
  ctx.drawImage(img, -pivX - ox, -pivY - oy);
  ctx.restore();
}

// antebraço: gira em torno do cotovelo e é posicionado por ele
function desenhaAntebraco(img, offX, offY, pivX, pivY, cotovelo, rotDeg){
  if(!ok(img)) return;
  bx.save();
  bx.translate(cotovelo.x, cotovelo.y);
  bx.rotate(rotDeg*D2R);
  bx.drawImage(img, -pivX, -pivY);
  bx.restore();
}

// true se a imagem já carregou
function ok(im){ return im && im.complete && im.naturalWidth>0; }

// camada recortada (pivo ja relativo ao recorte)
function blitOff(ctx, img, pivX, pivY, tgtX, tgtY, rotDeg){
  if(!ok(img)) return;
  ctx.save();
  ctx.translate(tgtX,tgtY);
  ctx.rotate(rotDeg*Math.PI/180);
  ctx.drawImage(img, -pivX, -pivY);
  ctx.restore();
}
// corpo inteiro pre-renderizado (1 blit por frame)
let bodyCacheFixo=null;
const _bodyCache={};
function makeBody(list){
  list=list||BODY;
  const key=list[0][0]+'|'+list.length;
  if(_bodyCache[key]!==undefined) return _bodyCache[key];
  for(const [f] of list){ if(!ok(IMG[f])) return null; }   // espera carregar
  const c=document.createElement('canvas'); c.width=CW; c.height=CH;
  const g=c.getContext('2d');
  for(const [f,x,y] of list) g.drawImage(IMG[f],x,y);
  _bodyCache[key]=c;
  return c;
}

const D2R=Math.PI/180;
const R2D=180/Math.PI;

// ============================================================
//  IK: resolve ângulos (ombro, antebraço) a partir de um alvo
//  de PUNHO no espaço. Usado nos gestos circulares.
// ============================================================
function ikAngulos(sh, tgt, l1, l2, bend){
  const dx=tgt.x-sh.x, dy=tgt.y-sh.y;
  let d=Math.hypot(dx,dy);
  d=Math.max(Math.abs(l1-l2)+0.5, Math.min(l1+l2-0.5, d));
  const base=Math.atan2(dy,dx);
  const cosA=(l1*l1+d*d-l2*l2)/(2*l1*d);
  const ang=Math.acos(Math.max(-1,Math.min(1,cosA)));
  const a=base+bend*ang;
  const el={x:sh.x+l1*Math.cos(a), y:sh.y+l1*Math.sin(a)};
  const wr={x:sh.x+Math.cos(base)*d, y:sh.y+Math.sin(base)*d};
  const up  =Math.atan2(el.y-sh.y, el.x-sh.x)*R2D;
  const fore=Math.atan2(wr.y-el.y, wr.x-el.x)*R2D;
  return {up:up, fore:fore, el:el, wr:wr};
}



// ============================================================
//  MEMBROS — peça única braço+antebraço.
//  A metade de cima gira no ombro; a de baixo gira no cotovelo.
//  O corte é na LINHA do cotovelo, então as metades se encontram
//  exatamente na junta — sem furo e sem emenda visível.
// ============================================================
//  meia-largura REAL do sprite, por linha (medida em build-time).
//  Usada para fechar a cunha do cotovelo com a medida exata do membro.
function perfilLargura(im, yTop, eixo){
  const c=document.createElement('canvas');
  c.width=im.naturalWidth; c.height=im.naturalHeight;
  const g=c.getContext('2d'); g.drawImage(im,0,0);
  const d=g.getImageData(0,0,c.width,c.height).data;
  const W=c.width, H=c.height, arr=new Float32Array(H);
  for(let y=0;y<H;y++){
    let e=-1, dr=-1;
    for(let x=0;x<W;x++){
      if(d[(y*W+x)*4+3]>40){ if(e<0) e=x; dr=x; }
    }
    arr[y] = (e<0) ? 0 : Math.max(eixo-e, dr-eixo);
  }
  return arr;
}
const _perfilCv = {};
function meiaLargura(M, l1){
  const im=IMG[M.src]; if(!ok(im)) return 34;
  if(!_perfilCv[M.src]) _perfilCv[M.src]=perfilLargura(im, M.ombro.y, M.ombro.x);
  const a=_perfilCv[M.src];
  const y=Math.round(M.ombro.y + l1);
  return (y>=0 && y<a.length && a[y]>0) ? a[y] : 34;
}

