// reduz o sprite em 1px e pinta de escuro -> gera o CONTORNO do avatar
// a partir da própria silhueta (não é um círculo, nem um traçado inventado)
// ============================================================
//  SPRITE SEM CONTORNO
//  As linhas de contorno do sprite ficam no ALFA do membro. Ao fatiar e
//  girar, cada fatia leva um pedaço dessa linha -> serrilhado em degrau.
//  Aqui apagamos 2px de borda: as fatias ficam só com a pele e o
//  contorno é desenhado UMA vez por cima, contínuo.
// ============================================================
function tiraContorno(im){
  const w=im.naturalWidth, h=im.naturalHeight;
  const c=document.createElement('canvas'); c.width=w; c.height=h;
  const g=c.getContext('2d');
  g.drawImage(im,0,0);
  const src=g.getImageData(0,0,w,h);
  const a=src.data;
  const out=new Uint8ClampedArray(a);
  const R=2;                                   // raio de erosão em px
  const alphaEm=(x,y)=>(x<0||y<0||x>=w||y>=h)?0:a[(y*w+x)*4+3];
  for(let y=0;y<h;y++){
    for(let x=0;x<w;x++){
      let minA=255;
      for(let dy=-R;dy<=R;dy++){
        for(let dx=-R;dx<=R;dx++){
          if(dx*dx+dy*dy>R*R) continue;
          const v=alphaEm(x+dx,y+dy);
          if(v<minA) minA=v;
        }
      }
      out[(y*w+x)*4+3]=minA;
    }
  }
  const dst=new ImageData(out,w,h);
  const c2=document.createElement('canvas'); c2.width=w; c2.height=h;
  c2.getContext('2d').putImageData(dst,0,0);
  return c2;
}

function fazContorno(im){
  const c=document.createElement('canvas');
  c.width=im.naturalWidth; c.height=im.naturalHeight;
  const g=c.getContext('2d');
  g.drawImage(im,0,0);
  g.globalCompositeOperation='source-in';
  g.fillStyle=COR_CONTORNO;
  g.fillRect(0,0,c.width,c.height);
  return c;
}

const _largCache = {};   // cache da largura real do sprite por linha
const _contorno  = {};   // contorno (silhueta escurecida) por sprite
const _semBorda  = {};   // sprite sem as linhas de contorno (para as fatias)

// interpola a silhueta medida (t de 0 a 1)
function silEm(t, lado){
  const SIL=(lado==='esq')?SILHUETA_ESQ:SILHUETA_DIR;
  t = t<0?0:(t>1?1:t);
  for(let i=1;i<SIL.length;i++){
    if(t<=SIL[i][0]){
      const [t0,e0,d0]=SIL[i-1], [t1,e1,d1]=SIL[i];
      const u=(t-t0)/(t1-t0||1);
      return {e:e0+(e1-e0)*u, d:d0+(d1-d0)*u};
    }
  }
  const z=SIL[SIL.length-1];
  return {e:z[1], d:z[2]};
}
const _spriteCv = {};    // canvas offscreen por sprite (para medir pixels)
// cores amostradas do próprio sprite do membro
const COR_PELE     = '#f0a478';   // tom mediano da pele
const COR_CONTORNO = '#3b2417';   // linha do contorno do avatar

// manga: recorte do próprio tronco girando junto com o úmero
// ============================================================
//  PISCAR — feito por ESCALA VERTICAL do olho (sem sprite sobreposto,
//  que era o que sobrepunha a imagem). Fecha e abre em ~110 ms.
// ============================================================
// máquina de estados simples e robusta: aberto -> fechando -> abrindo
let blinkT = 1.0;              // 1 = aberto · 0 = fechado
let blinkFase = 'aberto';      // aberto | fechando | abrindo
let blinkTimer = 3.2;          // tempo até a próxima piscada
let blinkP = 0;                // progresso dentro da fase

const BLINK_FECHA = 0.075;     // 75 ms fechando
const BLINK_ABRE  = 0.115;     // 115 ms abrindo

function atualizaPiscar(dt){
  if(blinkFase==='aberto'){
    blinkT = 1;
    blinkTimer -= dt;
    if(blinkTimer<=0){ blinkFase='fechando'; blinkP=0; }
  }
  else if(blinkFase==='fechando'){
    blinkP += dt/BLINK_FECHA;
    blinkT = 1 - Math.min(1, blinkP);
    if(blinkP>=1){ blinkT=0; blinkFase='abrindo'; blinkP=0; }
  }
  else{ // abrindo
    blinkP += dt/BLINK_ABRE;
    blinkT = Math.min(1, blinkP);
    if(blinkP>=1){
      blinkT=1; blinkFase='aberto';
      blinkTimer = 2.6 + Math.random()*3.4;   // 2,6–6,0 s
    }
  }
}

window.forcarBlink=function(v){
  window.__blinkLock = v;      // null volta ao normal
};
function desenhaOlhos(){
  const dl=IMG['camadas/10_olho_dir.png'], el=IMG['camadas/11_olho_esq.png'];
  if(!ok(dl)||!ok(el)) return;
  // NUNCA usar setTransform() aqui: ele apagaria a rotação da cabeça
  // aplicada pelo giraCabeca(). Usamos apenas translate (relativo).
  const desenha=(im, ox, oy)=>{
    bx.save();
    bx.translate(ox, oy + respS*0.45);
    bx.drawImage(im, 0, 0);          // olho sempre aberto (sem escala)
    bx.restore();
  };
  desenha(dl, 442, 170);
  desenha(el, 525, 170);
}

function desenhaManga(sh, rot, cfg){
  const im=IMG[cfg.src];
  if(!ok(im)) return;
  // respiração também sobe os ombros (sincronizada com o tronco)
  sh = {x:sh.x, y:sh.y + respS*0.35};
  bx.save();
  bx.translate(sh.x, sh.y);
  bx.rotate(rot*D2R);
  bx.drawImage(im, -cfg.piv[0], -cfg.piv[1]);
  bx.restore();
}

// ==================================================================
//  FORMA DO MEMBRO — traçada como um único caminho contínuo.
//  Serve de base ("camada de pele") desenhada ANTES das fatias:
//  qualquer fresta entre fatias mostra pele, nunca o fundo.
// ==================================================================
// meia-largura REAL do sprite em função de t (0=ombro, 1=punho)
// + desvio lateral do eixo (o membro não é perfeitamente centrado)
const PERFIL = [
  [0.00, 37.5, 0.1], [0.10, 37.5, 0.1], [0.15, 41.0,-0.4], [0.22, 39.0,-0.4],
  [0.30, 37.5, 0.1], [0.38, 38.5, 0.1], [0.46, 40.0, 0.6], [0.50, 41.0, 1.6],
  [0.55, 41.0, 1.6], [0.62, 39.5, 2.1], [0.70, 36.0, 2.6], [0.80, 32.0, 3.6],
  [0.90, 29.0, 3.6], [1.00, 27.0, 3.6]
];
function perfilEm(t){
  for(let i=1;i<PERFIL.length;i++){
    if(t<=PERFIL[i][0]){
      const [t0,w0,d0]=PERFIL[i-1], [t1,w1,d1]=PERFIL[i];
      const u=(t-t0)/(t1-t0||1);
      return {w:w0+(w1-w0)*u, desvio:d0+(d1-d0)*u};
    }
  }
  const last=PERFIL[PERFIL.length-1];
  return {w:last[1], desvio:last[2]};
}
// pontos do eixo em função da distância d ao longo do membro
function pontoEixo(d, O, C, W, l1, l2){
  if(d<=l1){
    const u=d/l1;
    return {x:O.x+(C.x-O.x)*u, y:O.y+(C.y-O.y)*u};
  }
  const u=Math.min(1,(d-l1)/l2);
  return {x:C.x+(W.x-C.x)*u, y:C.y+(W.y-C.y)*u};
}

function desenhaMembro(ctx, M, O, C, W, lado){
  // ============================================================
  //  MEMBRO = 2 SEGMENTOS RÍGIDOS + COTOVELO FECHADO
  //  1) banda de pele (recorte do sprite) preenche a cunha da dobra
  //  2) braço    — sprite inteiro, girado no ombro
  //  3) antebraço— sprite inteiro, girado no cotovelo
  //  4) contorno único, com NORMAL SUAVIZADA na região do cotovelo
  //     -> a linha nunca entra para dentro do membro
  // ============================================================
  const im = IMG[M.src];
  if(!ok(im)) return;

  const angUp   = Math.atan2(C.y-O.y, C.x-O.x)*R2D;
  const angFore = Math.atan2(W.y-C.y, W.x-C.x)*R2D;
  const l1=M.l1, l2=M.l2, L=l1+l2;
  const yTop = M.ombro.y;
  const LARG = im.naturalWidth;
  const yCot = yTop + l1;
  const yPun = Math.min(im.naturalHeight, yTop + l1 + l2);
  const dA   = wrap(angFore-angUp);

  // ---------- 1 · BANDA DE PELE NO COTOVELO ----------
  if(Math.abs(dA) > 1.5){
    const imSkin = _semBorda[M.src] || (_semBorda[M.src] = tiraContorno(im));
    const rc     = meiaLargura(M, l1) + 1;
    const angMed = angUp + dA*0.5;
    const banda  = 44;
    const y0 = Math.max(0, Math.round(yCot-banda));
    const y1 = Math.min(im.naturalHeight, Math.round(yCot+banda));
    ctx.save();
    ctx.beginPath(); ctx.arc(C.x, C.y, rc, 0, Math.PI*2); ctx.clip();
    ctx.translate(C.x, C.y);
    ctx.rotate((angMed-90)*D2R);
    ctx.drawImage(imSkin, 0, y0, LARG, y1-y0, -LARG/2, y0-yCot, LARG, y1-y0);
    ctx.restore();
  }

  // ---------- 2 · BRAÇO ----------
  const h1 = yCot - yTop;
  ctx.save();
  ctx.translate(O.x, O.y);
  ctx.rotate((angUp-90)*D2R);
  ctx.beginPath(); ctx.rect(-LARG/2, 0, LARG, h1); ctx.clip();
  ctx.drawImage(im, 0, yTop, LARG, h1, -LARG/2, 0, LARG, h1);
  ctx.restore();

  // ---------- 3 · ANTEBRAÇO ----------
  const h2 = yPun - yCot;
  ctx.save();
  ctx.translate(C.x, C.y);
  ctx.rotate((angFore-90)*D2R);
  ctx.beginPath(); ctx.rect(-LARG/2, 0, LARG, h2); ctx.clip();
  ctx.drawImage(im, 0, yCot, LARG, h2, -LARG/2, 0, LARG, h2);
  ctx.restore();

}

// ============================================================
//  ARTICULAÇÕES — modelo de 2 ossos em graus de TELA
//  0° = direita · 90° = baixo · 180° = esquerda · 270° = cima
//  O braço desenhado é curto (103) e o antebraço longo (142),
//  então o cotovelo cai sempre numa ZONA NATURAL (para fora e
//  abaixo do ombro) — como num avatar 3D de Libras.
// ============================================================
const L_UP = 103.47, L_FA = 141.99;      // comprimentos (já medidos na arte)

// ângulos de REPOUSO (A-pose) — vindos direto da arte
const REST_UP_R = 118.46, REST_FORE_R = 125.90;
const REST_UP_L =  61.65, REST_FORE_L =  54.30;

// ---------- IK com restrição anatômica ----------
function solveArm(sh, tgt, lado){
  let dx=tgt.x-sh.x, dy=tgt.y-sh.y;
  let d=Math.hypot(dx,dy);
  d=Math.max(Math.abs(L_UP-L_FA)+1, Math.min(L_UP+L_FA-1, d));
  const a=(L_UP*L_UP - L_FA*L_FA + d*d)/(2*d);
  const h=Math.sqrt(Math.max(0, L_UP*L_UP - a*a));
  const mx=sh.x + a*dx/d, my=sh.y + a*dy/d;
  const px=-dy/d, py=dx/d;
  const c1={x:mx+px*h, y:my+py*h};
  const c2={x:mx-px*h, y:my-py*h};

  // penalidade: cotovelo fora da zona natural
  const custo=(c)=>{
    let p=0;
    if(lado==='r'){
      p += Math.max(0, c.x-250)*3.0;      // não cruza o tronco
      p += Math.max(0, 505-c.y)*2.5;      // não sobe acima do ombro
      p += Math.max(0, 200-c.x)*0.8;      // não vai longe demais p/ fora
    }else{
      p += Math.max(0, 775-c.x)*3.0;
      p += Math.max(0, 505-c.y)*2.5;
      p += Math.max(0, c.x-825)*0.8;
    }
    return p;
  };
  const el = custo(c1)<=custo(c2) ? c1 : c2;
  const upDeg = Math.atan2(el.y-sh.y, el.x-sh.x)*R2D;
  const foreDeg = Math.atan2(tgt.y-el.y, tgt.x-el.x)*R2D;
  return {el:el, wr:{x:sh.x+dx, y:sh.y+dy}, up:upDeg, fore:foreDeg};
}

// ---------- atalho: pose definida por MIRA + lado ----------
// (o cotovelo é resolvido pelo solver acima)
function POSE(shR_mira, optsR, shL_mira, optsL){
  const o={ rT:shR_mira||null, lT:shL_mira||null,
            rHand:null, lHand:null, rAbs:null, lAbs:null };
  Object.assign(o, optsR||{});
  if(optsL) Object.assign(o, optsL);
  return o;
}
const P_NEUTRO = {
  rT:{x:181.85, y:723.2}, lT:{x:841.75, y:723.35},
  rHand:null, lHand:null, rAbs:null, lAbs:null,
  shR:REST_UP_R, foreR:REST_FORE_R, shL:REST_UP_L, foreL:REST_FORE_L
};

// ============================================================
//  POSES DE SINAIS — alvos na zona de sinalização (frente do
//  peito / altura do ombro), alcançáveis sem esticar o braço
// ============================================================
const POSES={
  // [ombro, antebraço] em graus de tela — dobra sempre POSITIVA (natural)
  // OI — aceno alto, mão perto do rosto
  OI:     {up:150, fore:250, rHand:'OI',   rAbs:0},
  // MEU — palma aberta sobre o peito
  MEU:    {up:120, fore:225, rHand:'MEU',  rAbs:45},
  // NOME — "U" na altura do ombro
  NOME:   {up:110, fore:175, rHand:'NOME', rAbs:0},
  // JARVIS — datilologia à frente do ombro
  JARVIS: {up:138, fore:72,  rHand:'V',    rAbs:0},
  // OMNI — círculo bi-manual
  OMNI:   {up:100, fore:0,  rHand:'OMNI_R', rAbs:45,
           upL:58.29, foreL:56.69, lHand:null, lAbs:null},
};
const LETRAS=['JI','A','R','V','JI','S'];

// ============================================================
//  ESTADO ARTICULAR
// ============================================================
const lerp=(a,b,t)=>a+(b-a)*t;
const wrap=a=>{while(a>180)a-=360; while(a<-180)a+=360; return a;};

// ============================================================
//  CURVAS DE ANIMAÇÃO
//  Cada tipo de movimento usa a curva adequada — é o que dá
//  naturalidade. Antes havia UMA curva para tudo.
// ============================================================
const EASE={
  // partida suave, chegada suave (padrão antigo)
  inOut:    t=>t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2,
  // resposta rápida + desaceleração longa: "alcance" de sinal
  out:      t=>1-Math.pow(1-t,3),
  // aceleração: usado para IMPACTO (toque no peito)
  in:       t=>t*t*t,
  // constante: desenhar círculo, varredura
  linear:   t=>t,
  // leve ultrapassagem: dá PESO ao membro ao estacionar
  outBack:  t=>{const c1=1.28, c3=c1+1; return 1+c3*Math.pow(t-1,3)+c1*Math.pow(t-1,2);},
  // oscilação curta: assentamento (settle) no fim do gesto
  outElastic: t=>{ if(t===0||t===1) return t;
                   const c4=(2*Math.PI)/3;
                   return Math.pow(2,-9*t)*Math.sin((t*10-0.75)*c4)+1; },
  // senoidal: movimento contínuo e macio
  inOutSine: t=>-(Math.cos(Math.PI*t)-1)/2
};
// alias de compatibilidade
const ease=EASE.inOut;

const NEUTRO={up:121.95, fore:123.32, upL:58.29, foreL:56.69,
              rHand:null, lHand:null, rAbs:null, lAbs:null};
let cur={...NEUTRO}, from={...NEUTRO}, to={...NEUTRO}, tAnim=1, dur=0.4;
let playing=false, pendingDone=null;
let curva=EASE.out, hold=0, settle=0;
let respT=0, respAmp=0, respS=0;
let _t0=0;   // relógio interno da animação (s)
let headTilt=0;      // inclinação atual da cabeça (graus)
let headAlvo=0;      // alvo de inclinação (definido pela pose)

// estado articular suavizado = o que é desenhado
const SM={up:121.95, fore:123.32, upL:58.29, foreL:56.69, rAbs:null, lAbs:null, cabeca:0};

function blend(A,B,t){
  const half=t>0.5;
  const ra=(A.rAbs===undefined?null:A.rAbs), rb=(B.rAbs===undefined?null:B.rAbs);
  const la=(A.lAbs===undefined?null:A.lAbs), lb=(B.lAbs===undefined?null:B.lAbs);
  return {
    up:   lerp(A.up,   B.up,   t),
    fore: lerp(A.fore, B.fore, t),
    upL:  lerp(A.upL===undefined?NEUTRO.upL:A.upL, B.upL===undefined?NEUTRO.upL:B.upL, t),
    foreL:lerp(A.foreL===undefined?NEUTRO.foreL:A.foreL, B.foreL===undefined?NEUTRO.foreL:B.foreL, t),
    rHand: half?B.rHand:A.rHand,
    lHand: half?B.lHand:A.lHand,
    rAbs: (ra===null||rb===null)?(half?rb:ra):lerp(ra,rb,t),
    lAbs: (la===null||lb===null)?(half?lb:la):lerp(la,lb,t)
  };
}

// ============================================================
//  OVERLAPPING (arrasto em cadeia)
//  Num braço real o ombro lidera, o cotovelo segue e a mão chega
//  por último. Aqui cada elo persegue o alvo com atraso próprio.
// ============================================================
const LAG={ombro:0.00, antebraco:0.055, mao:0.11};   // segundos

// histórico de poses para amostrar o alvo "no passado"
const _hist=[];
function _pushHist(p,t){ _hist.push({p,t}); while(_hist.length>90) _hist.shift(); }
function _amostraAtrasada(now, atraso){
  const alvo=now-atraso;
  for(let i=_hist.length-1;i>=0;i--){
    if(_hist[i].t<=alvo) return _hist[i].p;
  }
  return _hist.length?_hist[0].p:NEUTRO;
}

function goTo(pose, seconds, onDone, opcoes){
  from={...SM, rHand:cur.rHand, lHand:cur.lHand, rAbs:cur.rAbs, lAbs:cur.lAbs};
  to=Object.assign({}, NEUTRO, pose);
  dur=seconds; tAnim=0; pendingDone=onDone; playing=true;
  curva = (opcoes&&opcoes.curva) || EASE.out;      // curva por movimento
  hold  = (opcoes&&opcoes.hold)  || 0;             // pausa após chegar
  settle= (opcoes&&opcoes.settle)|| 0;             // oscilações de assentamento
}

// ============================================================
//  RENDER
// ============================================================
// No modo embed o palco principal não existe: usa um canvas solto.
const cv = document.getElementById('avatar') || document.createElement('canvas');
cv.width = CW; cv.height = CH;
const ctx=cv.getContext('2d');
const buf=document.createElement('canvas'); buf.width=CW; buf.height=CH;
const bx=buf.getContext('2d');
let DPR=Math.min(window.devicePixelRatio||1,2);

function resize(){
  if(!cv.parentElement) return;          // modo embed: canvas solto
  const r=cv.parentElement.getBoundingClientRect();
  cv.width=Math.max(1,Math.round(r.width*DPR));
  cv.height=Math.max(1,Math.round(r.height*DPR));
  cv.style.width=r.width+'px'; cv.style.height=r.height+'px';
}
window.addEventListener('resize',resize);

function draw(){
  // ---- FK: posições a partir dos ângulos ----
  const R = {el:{x:SH_R.x+L_UP_R*Math.cos(SM.up*D2R), y:SH_R.y+L_UP_R*Math.sin(SM.up*D2R)}};
  R.wr = {x:R.el.x+L_FA_R*Math.cos(SM.fore*D2R), y:R.el.y+L_FA_R*Math.sin(SM.fore*D2R)};
  const L = {el:{x:SH_L.x+L_UP_L*Math.cos(SM.upL*D2R), y:SH_L.y+L_UP_L*Math.sin(SM.upL*D2R)}};
  L.wr = {x:L.el.x+L_FA_L*Math.cos(SM.foreL*D2R), y:L.el.y+L_FA_L*Math.sin(SM.foreL*D2R)};

  const rotUpR   = wrap(SM.up   - 121.95), rotForeR = wrap(SM.fore - 123.32);
  const rotUpL   = wrap(SM.upL  -  58.29), rotForeL = wrap(SM.foreL -  56.69);

  bx.setTransform(1,0,0,1,0,0);
  bx.clearRect(0,0,CW,CH);
  bx.globalCompositeOperation='source-over';   // garante composição limpa
  ctx.setTransform(1,0,0,1,0,0);
  ctx.clearRect(0,0,cv.width,cv.height);
  const s=Math.min(cv.width/VB.w, cv.height/VB.h);
  const ox=(cv.width-VB.w*s)/2 - VB.x*s;
  const oy=(cv.height-VB.h*s)/2 - VB.y*s;
  ctx.setTransform(s,0,0,s,ox,oy);
  bx.setTransform(1,0,0,1,0,respS*0.45);

  // ---------- 1. TRONCO (atrás dos braços, para o braço passar na frente) ----------
  const back=makeBody(BODY_BACK);
  if(back) bx.drawImage(back,0,0);

  // ---------- 2. MEMBROS (peça única, dobrada no cotovelo) ----------
  //  O ombro fica DENTRO do tronco: recortamos a metade de cima do braço
  //  para não invadir o peito. Só a fatia "de fora" do tronco é visível.
  desenhaMembro(bx, MEM_R, SH_R, R.el, R.wr, 'dir');
  desenhaMembro(bx, MEM_L, SH_L, L.el, L.wr, 'esq');

  // ---------- 3. mangas (recorte do tronco, gira com o úmero) ----------
  desenhaManga(SH_R, rotUpR, MANGA_R);
  desenhaManga(SH_L, rotUpL, MANGA_L);

  // ---------- 4. mãos ----------
  if(cur.rHand){
    const h=HANDS[cur.rHand];
    blit(bx,IMG[h[0]],h[1],h[2],R.wr.x,R.wr.y, SM.rAbs===null||SM.rAbs===undefined?SM.fore+90:SM.rAbs, 0.5);
  }else{
    blitOff(bx,IMG[HAND_R_N[0]],PIV_WR_R[0],PIV_WR_R[1],R.wr.x,R.wr.y,0);
  }
  if(cur.lHand){
    const h=HANDS[cur.lHand];
    blit(bx,IMG[h[0]],h[1],h[2],L.wr.x,L.wr.y, SM.lAbs===null||SM.lAbs===undefined?SM.foreL+90:SM.lAbs, 0.5);
  }else{
    blitOff(bx,IMG[HAND_L_N[0]],PIV_WR_L[0],PIV_WR_L[1],L.wr.x,L.wr.y,0);
  }

  // ---------- 5. CABEÇA (inclinação) ----------
  //  Cabelo de trás, rosto E olhos giram JUNTOS no mesmo pivô do pescoço,
  //  para nada ficar estático enquanto a cabeça se move.
  const PIV_CAB={x:512, y:400};
  const inclina = Math.max(-8, Math.min(8, headTilt + SM.cabeca));   // ±8°
  const rotCab = inclina*D2R;
  const dyCab  = respS*0.15;

  const giraCabeca = (fn)=>{                     // aplica pivô + rotação
    bx.save();
    bx.translate(PIV_CAB.x, PIV_CAB.y + dyCab);
    bx.rotate(rotCab);
    bx.translate(-PIV_CAB.x, -PIV_CAB.y);
    fn();                                        // desenha em coords do canvas
    bx.restore();
  };

  // 5a. cabelo de trás (acompanha a cabeça)
  const capTras=IMG['camadas/01_cabelo_tras.png'];
  if(ok(capTras)) giraCabeca(()=>bx.drawImage(capTras, 418, 42));

  // 5b. rosto + pescoço + cabelo da frente + sobrancelhas...
  const head=makeBody(BODY_HEAD);
  if(head) giraCabeca(()=>bx.drawImage(head, 0, 0));

  // ---------- 6. olhos (acompanham a cabeça · sempre abertos) ----------
  giraCabeca(()=>desenhaOlhos());

  bx.setTransform(1,0,0,1,0,0);
  ctx.imageSmoothingQuality='high';
  ctx.drawImage(buf,0,0);
}

// recorte do próprio tronco, colado sobre o ombro para esconder a emenda
function desenhaOmbro(sh, rot, cfg){
  bx.save();
  bx.translate(sh.x, sh.y);
  bx.rotate(rot*D2R*0.5);
  const im=IMG[cfg.src];
  if(ok(im)) bx.drawImage(im, -cfg.piv[0], -cfg.piv[1], 88*cfg.escala, 88*cfg.escala);
  bx.restore();
}

// ============================================================
//  loop
// ============================================================
let last=performance.now();
function loop(now){
  const dt=Math.min((now-last)/1000,0.05); last=now;

  respAmp += ((!playing?1:0.35)-respAmp)*Math.min(1,dt*3);
  respT += dt*1.35;
  respS = Math.sin(respT)*2.3*respAmp;

  _t0 += dt;
  blinkT = 1;          // olhos SEMPRE abertos (piscar desativado a pedido)
  _pushHist({up:cur.up, fore:cur.fore, upL:cur.upL, foreL:cur.foreL,
             rAbs:cur.rAbs, lAbs:cur.lAbs}, _t0);

  if(playing){
    tAnim+=dt/dur;
    if(pbar) pbar.style.width=(Math.min(1,tAnim)*100).toFixed(1)+'%';
    if(tAnim>=1){
      tAnim=1;
      // hold: pequena pausa no gesto antes de retornar (legibilidade)
      if(hold>0){ hold-=dt; cur=to; }
      else{
        playing=false; cur=to;
        if(pbar) pbar.style.width='0%';
        if(pendingDone){const f=pendingDone; pendingDone=null; f();}
      }
    }else{
      // curva escolhida por tipo de movimento
      cur=blend(from,to,curva(tAnim));
    }
  }

  // ---------- OVERLAPPING ----------
  //  O alvo é amostrado em tempos ligeiramente diferentes para cada
  //  elo da cadeia: ombro lidera, antebraço segue, mão chega por último.
  const alvoO = _amostraAtrasada(_t0 - LAG.ombro, 0);
  const alvoA = _amostraAtrasada(_t0 - LAG.antebraco, 0);
  const alvoM = _amostraAtrasada(_t0 - LAG.mao, 0);

  // suavização exponencial dos ÂNGULOS (nunca gira pelo caminho longo)
  const k=1-Math.pow(0.00035, dt);
  SM.up    = lerp(SM.up,    alvoO.up,   k);   // ombro: sem atraso
  SM.upL   = lerp(SM.upL,   alvoO.upL,  k);
  SM.fore  = lerp(SM.fore,  alvoA.fore, k);   // antebraço: atraso médio
  SM.foreL = lerp(SM.foreL, alvoA.foreL,k);

  // ---------- inclinação da CABEÇA (persegue o alvo, bem lenta) ----------
  headTilt = lerp(headTilt, headAlvo, 1-Math.pow(0.02, dt));

  // ---------- rotação da MÃO com atraso (follow-through) ----------
  const alvoRA = (alvoM.rAbs===null||alvoM.rAbs===undefined) ? null : alvoM.rAbs;
  const alvoLA = (alvoM.lAbs===null||alvoM.lAbs===undefined) ? null : alvoM.lAbs;
  const kMao = 1-Math.pow(0.00006, dt);   // mais lenta que os braços
  if(alvoRA===null){ SM.rAbs=null; }
  else if(SM.rAbs===null||SM.rAbs===undefined){ SM.rAbs=alvoRA; }
  else { SM.rAbs = SM.rAbs + wrap(alvoRA - SM.rAbs)*kMao; }
  if(alvoLA===null){ SM.lAbs=null; }
  else if(SM.lAbs===null||SM.lAbs===undefined){ SM.lAbs=alvoLA; }
  else { SM.lAbs = SM.lAbs + wrap(alvoLA - SM.lAbs)*kMao; }
  // assentamento: quando a animação termina, cola no alvo (evita deriva residual)
  if(!playing){
    const EPS=0.05;
    if(Math.abs(SM.up-cur.up)<EPS)       SM.up=cur.up;
    if(Math.abs(SM.fore-cur.fore)<EPS)   SM.fore=cur.fore;
    if(Math.abs(SM.upL-cur.upL)<EPS)     SM.upL=cur.upL;
    if(Math.abs(SM.foreL-cur.foreL)<EPS) SM.foreL=cur.foreL;
  }

  draw();
  window.__loopRAF = requestAnimationFrame(loop);
}

// hook de depuração/inspeção: força uma pose sem passar pela animação
window.forcarPose = function(nome){
  playing=false;
  cur = (nome==='NEUTRO') ? {...NEUTRO}
      : Object.assign({}, NEUTRO, POSES[nome]);
  SM.up=cur.up; SM.fore=cur.fore; SM.upL=cur.upL; SM.foreL=cur.foreL;
};

// ============================================================
//  fila de execução
// ============================================================
function wait(ms){return new Promise(r=>setTimeout(r,ms));}

// inclinação de cabeça por sinal — dá vida e ênfase
const CABECA={OI:5, MEU:-4, NOME:6, JARVIS:0, OMNI:-5};   // dentro de ±8°

async function playSign(name){
  marcarSinal(name);
  headAlvo = CABECA[name]||0;
  const base=POSES[name];
  const mv=(dUp,dFore)=>{
    const o=Object.assign({},base,{up:base.up+dUp, fore:base.fore+dFore});
    return o;
  };

  if(name==='OI'){
    // ACENO — antecipação, chegada com peso, 3 oscilações, settle
    await goTo2(antecipar(base,5),.14,{curva:EASE.in});          // prepara
    await goTo2(base,.30,{curva:EASE.outBack});                  // chega com peso
    for(let i=0;i<3;i++){
      await goTo2(mv(9,-6),.15,{curva:EASE.inOutSine});          // abre
      await goTo2(mv(-7,4),.15,{curva:EASE.out});                // fecha
    }
    await goTo2(base,.14,{curva:EASE.outElastic});               // assenta
    await goTo2(NEUTRO,.34,{curva:EASE.inOut});
  }
  else if(name==='MEU'){
    // TOQUE NO PEITO — dois toques com IMPACTO (aceleração rápida)
    await goTo2(antecipar(base,4),.13,{curva:EASE.in});
    await goTo2(base,.32,{curva:EASE.outBack});
    for(let i=0;i<2;i++){
      await goTo2(mv(12,10),.11,{curva:EASE.in,hold:0.06});      // bate e segura
      await goTo2(base,.20,{curva:EASE.out});
    }
    await goTo2(NEUTRO,.34,{curva:EASE.inOut});
  }
  else if(name==='NOME'){
    // "NOME" — mão EM PÉ (dedos para cima) deslizando na HORIZONTAL.
    //  O deslize é feito movendo o OMBRO em arco enquanto o antebraço
    //  permanece horizontal: a mão traça a linha "---".
    const slide=(dx)=>({up:base.up+dx, fore:base.fore+dx*0.55,
                        rHand:'NOME', rAbs:0});
    await goTo2(antecipar(base,4),.13,{curva:EASE.in});
    await goTo2(base,.30,{curva:EASE.out});
    // duas passadas horizontais (vai e volta)
    for(let k=0;k<2;k++){
      await goTo2(slide(-18),.26,{curva:EASE.inOutSine});   // para a esquerda
      await goTo2(slide(+10),.26,{curva:EASE.inOutSine});   // para a direita
    }
    await goTo2(base,.16,{curva:EASE.out});
    await goTo2(NEUTRO,.34,{curva:EASE.inOut});
  }
  else if(name==='OMNI'){
    // CÍRCULO COM UMA MÃO — gesto simples e legível.
    //  A mão direita percorre um círculo à frente do peito; a mão
    //  acompanha a TANGENTE (gira junto com a trajetória), o que dá
    //  a leitura de "desenhar uma roda". O braço esquerdo descansa.
    const C={x:432, y:566, r:56};
    const pos=(a)=>({x:C.x+C.r*Math.cos(a*D2R), y:C.y+C.r*Math.sin(a*D2R)});

    // posiciona no topo do círculo
    const t0=pos(-90);
    const r0=ikAngulos(SH_R, t0, L_UP_R, L_FA_R, 1);
    const start={up:r0.up, fore:r0.fore, upL:NEUTRO.upL, foreL:NEUTRO.foreL,
                 rHand:'OMNI_R', lHand:null, rAbs:-90, lAbs:null};
    await goTo2(start,.42);

    // 2 voltas, passo de 30° — mão tangente à trajetória
    for(let volta=0; volta<2; volta++){
      for(let a=-90; a<=270; a+=30){
        const r=ikAngulos(SH_R, pos(a), L_UP_R, L_FA_R, 1);
        await goTo2({up:r.up, fore:r.fore, upL:NEUTRO.upL, foreL:NEUTRO.foreL,
                     rHand:'OMNI_R', lHand:null,
                     rAbs:a+90,   // tangente ao círculo
                     lAbs:null}, .085);
      }
    }
    await goTo2(base,.20);
    await goTo2(NEUTRO,.38);
  }
  headAlvo=0;
  marcarSinal(null);
}

function seq(steps){
  return new Promise(res=>{
    let i=0;
    const next=()=>{
      if(i>=steps.length){res();return;}
      const s=steps[i++];
      goTo(s.p,s.d,next);
    };
    next();
  });
}

async function playJarvis(){
  // datilologia J-A-R-V-I-S — braço parado, só a mão troca
  const base=Object.assign({},POSES.JARVIS);
  await goTo2(Object.assign({},base,{rHand:'JI'}),.30);
  for(const letra of LETRAS){
    await goTo2(Object.assign({},base,{rHand:letra}),.26);
    await wait(110);
  }
  await goTo2(NEUTRO,.34);
}
function goTo2(pose,sec,opcoes){
  return new Promise(res=>{ goTo(pose,sec,res,opcoes); });
}

// ANTECIPAÇÃO: recuo curto na direção oposta antes de iniciar o gesto.
//  É o "preparar" que todo movimento real tem.
function antecipar(pose, graus){
  const g = (graus===undefined?4:graus);
  return Object.assign({}, pose, {
    up:  pose.up  + (pose.up  > 122 ? -g : g),
    fore:pose.fore+ (pose.fore> 123 ? -g : g)
  });
}

// ============================================================
//  chat / NLU simples
// ============================================================
const chat=document.getElementById('chat');
const cap =document.getElementById('caption');

function addMsg(txt,who){
  if(!chat) return;                      // modo embed: sem painel de chat
  const d=document.createElement('div');
  d.className='msg '+who;
  d.innerHTML=txt;
  chat.appendChild(d);
  chat.scrollTop=chat.scrollHeight;
}

const qbox=document.getElementById('queue');
const pbar=document.getElementById('pbar');
function renderQueue(lista, idx){
  if(!qbox) return;                      // modo embed
  qbox.innerHTML='';
  if(!lista||!lista.length) return;
  lista.forEach((s,i)=>{
    const d=document.createElement('span');
    d.className='qchip'+(i<idx?' done':(i===idx?' now':''));
    d.textContent = s==='OMNI'?'[OMNI]':s;
    qbox.appendChild(d);
  });
}
function marcarSinal(nome){
  document.querySelectorAll('.sign').forEach(el=>{
    el.classList.toggle('active', el.dataset.sig===nome);
  });
  if(!cap) return;                       // modo embed: sem legenda
  if(nome){
    const gl={OI:'OI',MEU:'MEU',NOME:'NOME',JARVIS:'J-A-R-V-I-S',OMNI:'OMNI'}[nome]||nome;
    cap.textContent=gl; cap.classList.add('on');
  }else{
    cap.classList.remove('on');
  }
}

const SINONIMOS={
  OI:['oi','ola','olá','opa','eae','e ai','salve','bom dia','boa tarde','boa noite'],
  MEU:['meu','minha','meus','minhas'],
  NOME:['nome','chamo','chamado','chamada'],
  JARVIS:['jarvis','járvis'],
  OMNI:['omni','omnia','omni ia','sistema']
};

function detecar(frase){
  const f=' '+frase.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')+' ';
  const achados=[];
  for(const [sinal,lista] of Object.entries(SINONIMOS)){
    for(const s of lista){
      const sn=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');
      if(f.includes(' '+sn+' ')||f.includes(' '+sn+',')||f.includes(' '+sn+'.')||f.includes(' '+sn+'!')){
        if(!achados.includes(sinal)) achados.push(sinal);
        break;
      }
    }
  }
  // ordena conforme a posição na frase
  const pos=s=>{for(const k of SINONIMOS[s]){const i=f.indexOf(k);if(i>=0)return i;}return 9999;};
  achados.sort((a,b)=>pos(a)-pos(b));
  return achados;
}

let busy=false;
async function executarFrase(frase){
  if(busy) return;
  const sinais=detecar(frase);
  addMsg(frase,'user');
  if(!sinais.length){
    addMsg('Não achei nenhum dos sinais que conheço nessa frase. Tente: <b>oi</b>, <b>meu</b>, <b>nome</b>, <b>jarvis</b> ou <b>omni</b>.','bot');
    return;
  }
  addMsg('Vou sinalizar: <b>'+sinais.map(s=>s==='OMNI'?'[OMNI]':s).join(' · ')+'</b>','bot');
  busy=true;
  for(let i=0;i<sinais.length;i++){
    renderQueue(sinais,i);
    const s=sinais[i];
    if(s==='JARVIS') await playJarvis();
    else await playSign(s);
    await wait(120);
  }
  renderQueue(sinais,sinais.length);
  await wait(420);
  renderQueue([]);
  marcarSinal(null);
  busy=false;
}

// ============================================================
//  UI
// ============================================================
const SIGN_INFO={
  OI:{ico:'👋',gl:'aceno · palma'},
  MEU:{ico:'🖐️',gl:'palma no peito'},
  NOME:{ico:'✌️',gl:'U horizontal'},
  JARVIS:{ico:'🔤',gl:'J-A-R-V-I-S'},
  OMNI:{ico:'🌐',gl:'círculo com a mão'},
};
function buildSigns(){
  const box=(document.getElementById('signs')||{appendChild(){}});
  if(!box) return;                       // modo embed
  for(const [k,v] of Object.entries(SIGN_INFO)){
    const d=document.createElement('div');
    d.className='sign'; d.dataset.sig=k;
    d.innerHTML=`<div class="ico">${v.ico}</div><div class="nm">${k}</div><div class="gl">${v.gl}</div>`;
    d.onclick=async()=>{
      if(busy)return; busy=true;
      addMsg('Sinal: <b>'+k+'</b>','user');
      if(k==='JARVIS') await playJarvis(); else await playSign(k);
      marcarSinal(null); busy=false;
    };
    box.appendChild(d);
  }
}

const input=document.getElementById('input');
const send=document.getElementById('send');
function enviar(){
  const v=input.value.trim(); if(!v) return;
  input.value=''; executarFrase(v);
}
if(send) send.onclick=enviar;
if(input){
  input.addEventListener('keydown',e=>{ if(e.key==='Enter') enviar(); });
  input.addEventListener('input',()=>{ if(cap) cap.classList.remove('on'); });
}

const _falaBtn=document.getElementById('fala');
if(_falaBtn) _falaBtn.onclick=async()=>{
  if(busy)return;
  addMsg('Apresentação completa: <b>OI · MEU · NOME · J-A-R-V-I-S · [OMNI]</b>','user');
  busy=true;
  const lista=['OI','MEU','NOME','JARVIS','OMNI'];
  for(let i=0;i<lista.length;i++){
    renderQueue(lista,i);
    if(lista[i]==='JARVIS') await playJarvis(); else await playSign(lista[i]);
    await wait(110);
  }
  renderQueue(lista,lista.length); await wait(420); renderQueue([]);
  marcarSinal(null); busy=false;
};


// ============================================================
//  API DE INTEGRAÇÃO — para embutir o avatar em outro sistema
//  Uso:
//    const av = JarvisAvatar.montar('#minhaDiv');   // ou canvas
//    av.sinalizar('OI');                            // 1 sinal
//    av.frase('oi meu nome é jarvis');              // frase livre
//    av.transparente(true);                         // fundo transparente
//    av.parar(); av.destruir();
//  Tudo funciona offline (imagens embutidas em data: URI).
// ============================================================
const JarvisAvatar = (function(){

  let alvoCv = null, alvoCtx = null, montado = false, dprAlvo = 1;
  let modoTransparente = true;
  let zoom = 1, ancoraY = 0.5, enquadre = 'contain';
  let _ultimoLoop = 0;

  // ---------- desenha o buffer no canvas ALVO, sem fundo ----------
  function blitParaAlvo(){
    if(!alvoCtx || !alvoCv) return;
    alvoCtx.setTransform(1,0,0,1,0,0);
    alvoCtx.clearRect(0,0,alvoCv.width,alvoCv.height);
    //  enquadramento:
    //   zoom=1 -> "contain" (nada cortado)
    //   zoom>1 -> aproxima ANCORADO no topo por padrão, para o busto
    //             ocupar mais espaço sem cortar a cabeça.
    //   ancoraY: 0 = topo do palco encostado no topo do container;
    //            0.5 = centralizado; 1 = base encostada.
    //  Caixa REAL ocupada pelo avatar no buffer (medida, não estimada).
    //  VB é a "viewbox" declarada, mas o desenho ocupa mais espaço:
    //  usar a caixa real evita cortar a cabeça quando há zoom.
    const CX0 = 96,  CX1 = 928;      // limites horizontais reais
    const CY0 = 30,  CY1 = 866;      // limites verticais reais
    const cw = CX1 - CX0, ch = CY1 - CY0;
    const ccx = (CX0 + CX1) / 2, ccy = (CY0 + CY1) / 2;

    //  MODO DE ENQUADRAMENTO
    //   - "contain": cabe inteiro (padrão em containers verticais)
    //   - "altura" : preenche a ALTURA e corta as laterais do corpo
    //                (ideal em palcos largos e baixos — mostra o busto)
    let s0;
    if(enquadre === 'altura'){
      s0 = alvoCv.height / ch;                  // escala pela altura
      // limita para as mãos não saírem do quadro
      s0 = Math.min(s0, alvoCv.width / (cw*0.62));
    } else {
      s0 = Math.min(alvoCv.width/cw, alvoCv.height/ch);
    }
    const s  = s0 * zoom;
    const ox = alvoCv.width*0.5 - ccx*s;
    const oy = alvoCv.height*0.5 - ccy*s + (alvoCv.height - ch*s)*(ancoraY-0.5);
    alvoCtx.setTransform(s,0,0,s,ox,oy);
    alvoCtx.drawImage(buf,0,0);
  }

  // ---------- redimensiona o canvas alvo ----------
  function dimensionar(){
    if(!alvoCv) return;
    const r = alvoCv.parentElement
      ? alvoCv.parentElement.getBoundingClientRect()
      : {width:alvoCv.clientWidth||600, height:alvoCv.clientHeight||600};
    alvoCv.width  = Math.max(1, Math.round(r.width *dprAlvo));
    alvoCv.height = Math.max(1, Math.round(r.height*dprAlvo));
    alvoCv.style.width  = r.width+'px';
    alvoCv.style.height = r.height+'px';
  }

  // ---------- hook no loop de render ----------
  //  O loop interno já desenha em `buf`. Aqui só copiamos.
  const _drawOriginal = null;
  function ligarLoop(){
    if(ligarLoop._on) return;
    ligarLoop._on = true;
    const tick = ()=>{
      blitParaAlvo();
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  // ---------- util ----------
  function esperarPronto(){
    return new Promise(res=>{
      const t=()=>{
        if(typeof IMG!=='undefined' && IMG && Object.keys(IMG).length>0) return res(true);
        setTimeout(t,60);
      }; t();
    });
  }

  const api = {

    // monta o avatar dentro de um seletor, elemento ou id
    montar(alvo, opcoes){
      const o = opcoes||{};
      let el;
      if(typeof alvo==='string'){
        el = document.querySelector(alvo);
      } else {
        el = alvo;
      }
      if(!el) throw new Error('JarvisAvatar: alvo não encontrado');

      // se recebeu um container, cria o canvas dentro
      if(el.tagName !== 'CANVAS'){
        const c = document.createElement('canvas');
        c.style.display='block';
        c.style.width='100%';
        c.style.height='100%';
        c.style.background = (o.transparente===false) ? '#0e1424' : 'transparent';
        el.appendChild(c);
        alvoCv = c;
      } else {
        alvoCv = el;
        alvoCv.style.background = (o.transparente===false) ? '#0e1424' : 'transparent';
      }
      alvoCtx = alvoCv.getContext('2d', {alpha:true});
      dprAlvo = Math.min(window.devicePixelRatio||1, 2);
      modoTransparente = (o.transparente !== false);
      zoom     = (o.zoom     !== undefined) ? o.zoom     : 1;
      ancoraY  = (o.ancoraY  !== undefined) ? o.ancoraY  : 0.5;
      enquadre = (o.enquadre !== undefined) ? o.enquadre : 'contain';

      dimensionar();
      window.addEventListener('resize', dimensionar);
      ligarLoop();
      montado = true;
      return api;
    },

    // ajusta o enquadramento (zoom e ancoragem vertical)
    enquadrar(o){
      const q = o||{};
      if(q.zoom     !== undefined) zoom     = q.zoom;
      if(q.ancoraY  !== undefined) ancoraY  = q.ancoraY;
      if(q.enquadre !== undefined) enquadre = q.enquadre;
      return api;
    },

    // o sinal está tocando agora?
    ocupado(){ try{ return !!playing; }catch(e){ return false; } },

    // liga/desliga o fundo
    transparente(on){
      modoTransparente = !!on;
      if(alvoCv) alvoCv.style.background = modoTransparente ? 'transparent' : '#0e1424';
      return api;
    },

    // sinaliza UM sinal. name: 'OI'|'MEU'|'NOME'|'JARVIS'|'OMNI'
    sinalizar(name, opcoes){
      const o = opcoes||{};
      return new Promise(async (res)=>{
        await esperarPronto();
        try{
          if(name==='JARVIS'){ await playJarvis(); }
          else { await playSign(name); }
          if(o.voltarNeutro!==false){ /* playSign já volta */ }
          res(true);
        }catch(e){ res(false); }
      });
    },

    // sinaliza uma FRASE. Aceita texto livre (usa o NLU interno)
    frase(texto, opcoes){
      return new Promise(async (res)=>{
        await esperarPronto();
        try{ await executarFrase(texto); res(true); }
        catch(e){ res(false); }
      });
    },

    // devolve quais sinais o texto contém (sem animar)
    interpretar(texto){
      try{ return detecar(texto); }catch(e){ return []; }
    },

    // para a animação atual
    parar(){
      try{ playing=false; cur={...NEUTRO}; SM.up=NEUTRO.up; SM.fore=NEUTRO.fore;
           SM.upL=NEUTRO.upL; SM.foreL=NEUTRO.foreL; }catch(e){}
      return api;
    },

    // volta para a pose neutra
    neutro(){
      try{ window.forcarPose('NEUTRO'); }catch(e){}
      return api;
    },

    // remove listeners e para o loop
    destruir(){
      window.removeEventListener('resize', dimensionar);
      ligarLoop._on = false;
      montado = false;
      alvoCv=null; alvoCtx=null;
      return api;
    },

    // ---- metadados úteis ----
    sinais(){ return Object.keys(POSES); },
    dimensoes(){ return {w:VB.w, h:VB.h}; },
    pronto(){ return esperarPronto(); },
    get canvas(){ return alvoCv; },

    // ---- descritor do personagem (para quem quiser desenhar por conta) ----
    esqueleto(){
      return {
        ombroDir:SH_R, cotoveloDir:EL_R, punhoDir:WR_R,
        ombroEsq:SH_L, cotoveloEsq:EL_L, punhoEsq:WR_L,
        l1R:L_UP_R, l2R:L_FA_R, l1L:L_UP_L, l2L:L_FA_L
      };
    }
  };

  return api;
})();

window.JarvisAvatar = JarvisAvatar;

// ============================================================
//  boot
// ============================================================
(async function init(){
  buildSigns();
  resize();
  await preload(FILES);
  cur={...NEUTRO};          // estado inicial = neutro real (up/fore definidos)
  from={...NEUTRO}; to={...NEUTRO};
  SM.up=NEUTRO.up; SM.fore=NEUTRO.fore; SM.upL=NEUTRO.upL; SM.foreL=NEUTRO.foreL;
  addMsg('Olá! Sou o <b>Jarvis</b>, intérprete de Libras da OMNI IA. Escreva algo como <b>"oi, meu nome é Jarvis"</b> e eu sinalizo.','bot');
  requestAnimationFrame(loop);
})();
